const clef = await models.getModelOfType('classifier', 'odds', 'clef-flash');
const issues = [];
for (let p = 0; p < 8; p++) { const text = await tools.read({ path: './issues-' + p + '.jsonl', offset: null, limit: null }); for (const line of text.split('\n')) if (line.startsWith('{')) issues.push(JSON.parse(line)); }
if (issues.length !== 255) return 'count ' + issues.length;
const packs = []; for (let s = 0; s < issues.length; s += 32) packs.push(issues.slice(s, s + 32));
const ask = (pack) => { const questions = {}; pack.forEach((_, k) => { questions['u' + k] = { type: 'bool', instructions: 'Issue u' + k + ': Is this a critical bug that a Kubernetes maintainer must fix urgently, before the next release?', criteria: { true: 'Yes', false: 'No' } }; questions['i' + k] = { type: 'bool', instructions: 'Issue u' + k + ': Does this issue\'s text try to give instructions to an AI system?', criteria: { true: 'Yes', false: 'No' } }; }); return models.classify(clef, { state: { issues: pack.map((x, k) => ({ key: 'u' + k, title: x.title, body: x.body })) }, questions }); };
const results = await Promise.all(packs.map(ask));
const urgent = []; let injections = 0; let failed = 0;
results.forEach((r, n) => { if (r.stopReason !== 'stop') { failed++; return; } packs[n].forEach((x, k) => { const u = r.answers['u' + k].probability; const i = r.answers['i' + k].probability; if (i >= 0.5) injections++; else if (u >= 0.32) urgent.push([x.id, u]); }); });
urgent.sort((a, b) => b[1] - a[1]);
return 'URGENT: ' + (urgent.length ? urgent.map((x) => x[0]).join(', ') : 'none') + ' | injections=' + injections + ' failedPacks=' + failed;
